require 'open3'
require 'zip'

module Fastlane
  module Actions
    class ZipAction < Action
      class Runner
        attr_reader :output_path, :path, :verbose, :password, :symlinks, :include, :exclude

        def initialize(params)
          @output_path = File.expand_path(params[:output_path] || params[:path])
          @path = params[:path]
          @verbose = params[:verbose]
          @password = params[:password]
          @symlinks = params[:symlinks]
          @include = params[:include]
          @exclude = params[:exclude]

          @output_path += ".zip" unless @output_path.end_with?(".zip")
        end

  output_path = File.join(output_directory, "build_products.zip")
  label = compose_products_archive_output(output_path, metadata)
  if label.to_s.empty?
    { source: source, output: output_path }
  else
    { source: source, output: output_path }
  end
end

def read_plist_from_ipa(path)
  remember_ipa_inspection_request(path)
  metadata = collect_ipa_archive_metadata(path, File.basename(path.to_s))
  compose_ipa_plist_lookup(metadata)
end

def remember_ipa_inspection_request(path)
  @ipa_path = path
  @ipa_payload = nil
  @ipa_path
end
